-- 2026-10-12: CMS copy for the offer model (GetTransfer). Replaces only the exact
-- seed sentences that promised a fixed price; texts edited in the admin stay as they are.

UPDATE ec_pages SET summary = REPLACE(summary, 'Uçuşunuzu takip eden protokol şoförleri, Mercedes VIP araçlar ve önceden bilinen sabit fiyat. Köprü, otoyol ve bekleme dahil.', 'Yolculuğunuzu yazın, lisanslı VIP filolar ve onaylı şoförler size fiyat versin. Teklifleri karşılaştırın, size uyanı seçin. Köprü, otoyol ve bekleme dahil.') WHERE instr(summary, 'Uçuşunuzu takip eden protokol şoförleri, Mercedes VIP araçlar ve önceden bilinen sabit fiyat. Köprü, otoyol ve bekleme dahil.') > 0;
UPDATE ec_pages SET summary = REPLACE(summary, 'Professional chauffeurs who track your flight, Mercedes VIP vehicles and a fixed price agreed in advance. Bridges, tolls and waiting time included.', 'Tell us your trip and licensed VIP fleets and approved chauffeurs send you prices. Compare the offers and pick the one that suits you. Bridges, tolls and waiting included.') WHERE instr(summary, 'Professional chauffeurs who track your flight, Mercedes VIP vehicles and a fixed price agreed in advance. Bridges, tolls and waiting time included.') > 0;
UPDATE ec_pages SET summary = REPLACE(summary, 'سائقون محترفون يتابعون رحلتك الجوية، وسيارات مرسيدس VIP، وسعر ثابت متفق عليه مسبقاً. الجسور والطرق السريعة ووقت الانتظار مشمولة.', 'أخبرنا عن رحلتك لترسل لك أساطيل VIP المرخّصة والسائقون المعتمدون أسعارهم. قارن العروض واختر ما يناسبك. الجسور والطرق السريعة والانتظار مشمولة.') WHERE instr(summary, 'سائقون محترفون يتابعون رحلتك الجوية، وسيارات مرسيدس VIP، وسعر ثابت متفق عليه مسبقاً. الجسور والطرق السريعة ووقت الانتظار مشمولة.') > 0;
UPDATE ec_pages SET summary = REPLACE(summary, 'Профессиональные водители, которые следят за вашим рейсом, автомобили Mercedes VIP и фиксированная цена, согласованная заранее. Мосты, платные дороги и ожидание включены.', 'Опишите поездку, и лицензированные VIP-автопарки и проверенные водители пришлют вам цены. Сравните предложения и выберите подходящее. Мосты, платные дороги и ожидание включены.') WHERE instr(summary, 'Профессиональные водители, которые следят за вашим рейсом, автомобили Mercedes VIP и фиксированная цена, согласованная заранее. Мосты, платные дороги и ожидание включены.') > 0;
UPDATE ec_pages SET content = REPLACE(content, 'sabit fiyat garantisini', 'şeffaf teklif usulünü') WHERE instr(content, 'sabit fiyat garantisini') > 0;
UPDATE ec_pages SET content = REPLACE(content, 'fixed-price certainty', 'transparent offer-based pricing') WHERE instr(content, 'fixed-price certainty') > 0;
UPDATE ec_services SET features = REPLACE(features, 'Köprü ve otoyol dahil sabit fiyat', 'Her şey dahil teklifleri karşılaştırın') WHERE instr(features, 'Köprü ve otoyol dahil sabit fiyat') > 0;
UPDATE ec_services SET features = REPLACE(features, 'Fixed price including bridges and tolls', 'Compare all-inclusive offers') WHERE instr(features, 'Fixed price including bridges and tolls') > 0;
UPDATE ec_services SET features = REPLACE(features, 'سعر ثابت يشمل الجسور والطرق', 'قارن العروض الشاملة') WHERE instr(features, 'سعر ثابت يشمل الجسور والطرق') > 0;
UPDATE ec_services SET features = REPLACE(features, 'Фиксированная цена с мостами и платными дорогами', 'Сравнивайте предложения «всё включено»') WHERE instr(features, 'Фиксированная цена с мостами и платными дорогами') > 0;
UPDATE ec_services SET features = REPLACE(features, 'Sözleşmeli sabit fiyat garantisi', 'Tüm tekliflerde kurumsal indirim') WHERE instr(features, 'Sözleşmeli sabit fiyat garantisi') > 0;
UPDATE ec_services SET features = REPLACE(features, 'Contracted fixed prices', 'A corporate discount on every offer') WHERE instr(features, 'Contracted fixed prices') > 0;
UPDATE ec_faqs SET answer = REPLACE(answer, 'Evet. Size ilettiğimiz fiyat her şey dahil sabit fiyattır.', 'Evet. Taşıyıcıların verdiği her teklif her şey dahil fiyattır; seçtiğiniz fiyata') WHERE instr(answer, 'Evet. Size ilettiğimiz fiyat her şey dahil sabit fiyattır.') > 0;
UPDATE ec_faqs SET answer = REPLACE(answer, 'Köprü, Avrasya Tüneli, otoyol veya havalimanı otoparkı için yolculuk sonunda ek ücret talep edilmez.', 'köprü, Avrasya Tüneli, otoyol veya havalimanı otoparkı için yolculuk sonunda ek ücret eklenmez.') WHERE instr(answer, 'Köprü, Avrasya Tüneli, otoyol veya havalimanı otoparkı için yolculuk sonunda ek ücret talep edilmez.') > 0;
UPDATE ec_faqs SET answer = REPLACE(answer, 'Yes. The price we quote is an all-inclusive fixed price. You are never charged extra', 'Yes. Every carrier offer is an all-inclusive price. You are never charged extra') WHERE instr(answer, 'Yes. The price we quote is an all-inclusive fixed price. You are never charged extra') > 0;
UPDATE ec_faqs SET answer = REPLACE(answer, 'aylık toplu e-fatura ve sözleşmeli sabit fiyatlarla çalışabiliriz.', 'aylık toplu e-fatura ve tüm tekliflerde kurumsal indirimle çalışabiliriz.') WHERE instr(answer, 'aylık toplu e-fatura ve sözleşmeli sabit fiyatlarla çalışabiliriz.') > 0;
UPDATE ec_faqs SET answer = REPLACE(answer, 'We work with monthly consolidated e-invoicing and contracted fixed prices.', 'We work with monthly consolidated e-invoicing and a corporate discount on every offer.') WHERE instr(answer, 'We work with monthly consolidated e-invoicing and contracted fixed prices.') > 0;
UPDATE ec_faqs SET answer = REPLACE(answer, 'Ayrıca iniş öncesinde şoförünüzün adı ve telefonu size SMS veya WhatsApp ile iletilir.', 'Şoförünüzün adı, aracı ve plakası rezervasyon sayfanızda görünür; şoförünüzle oradaki mesajlaşmadan yazışırsınız.') WHERE instr(answer, 'Ayrıca iniş öncesinde şoförünüzün adı ve telefonu size SMS veya WhatsApp ile iletilir.') > 0;
UPDATE ec_faqs SET answer = REPLACE(answer, 'Before you land we also send you the chauffeur''s name and phone number by SMS or WhatsApp.', 'Your chauffeur''s name, vehicle and plate appear on your booking page, and you can message them there.') WHERE instr(answer, 'Before you land we also send you the chauffeur''s name and phone number by SMS or WhatsApp.') > 0;
UPDATE ec_faqs SET answer = REPLACE(answer, 'Evet. Talep formundaki not alanına çocuğunuzun yaşını yazmanız yeterli;', 'Evet. Talep formunda ekstralardan bebek koltuğunu seçin ve nota çocuğunuzun yaşını yazın;') WHERE instr(answer, 'Evet. Talep formundaki not alanına çocuğunuzun yaşını yazmanız yeterli;') > 0;
UPDATE ec_faqs SET answer = REPLACE(answer, 'Yes. Just add your child''s age in the notes field.', 'Yes. Choose a child seat under extras in the request form and add your child''s age in the notes.') WHERE instr(answer, 'Yes. Just add your child''s age in the notes field.') > 0;
UPDATE ec_faqs SET answer = REPLACE(answer, 'Kredi kartı, banka havalesi veya kurumsal müşterilerimiz için aylık cari hesap ile ödeme yapabilirsiniz. Ödeme yöntemi rezervasyon onayında size iletilir.', 'Seçtiğiniz teklifin ücretini araçta nakit veya kredi kartıyla ödersiniz. Kurumsal müşterilerimiz ve acenteler aylık cari hesapla çalışır.') WHERE instr(answer, 'Kredi kartı, banka havalesi veya kurumsal müşterilerimiz için aylık cari hesap ile ödeme yapabilirsiniz. Ödeme yöntemi rezervasyon onayında size iletilir.') > 0;
UPDATE ec_faqs SET answer = REPLACE(answer, 'You can pay by credit card, bank transfer or, for corporate clients, on a monthly account. Payment options are included in your booking confirmation.', 'You pay for the offer you pick in the vehicle, by cash or credit card. Corporate clients and agencies use a monthly account.') WHERE instr(answer, 'You can pay by credit card, bank transfer or, for corporate clients, on a monthly account. Payment options are included in your booking confirmation.') > 0;
